import {createCDGDecoder} from './cdg.js';
const $=selector=>document.querySelector(selector),checks=[];
const packet=(op,data=[],command=9)=>{const p=new Uint8Array(24);p[0]=command;p[1]=op;p.set(data,4);return p;};
const join=(...items)=>{const bytes=new Uint8Array(items.length*24);items.forEach((p,i)=>bytes.set(p,i*24));return bytes;};
const colors=[0,0xf00,0x0f0,0x00f,0xff0,0x0ff,0xf0f,0x888,0x123,0x456,0x789,0xabc,0xdef,0x135,0x579,0xfff];
const clut=(high=false,list=colors)=>packet(high?31:30,list.slice(high?8:0,high?16:8).flatMap(c=>[(c>>6)&63,c&63]));
const tile=(row=8,column=20,color0=0,color1=1,bits=Array(12).fill(63),xor=false)=>packet(xor?38:6,[color0,color1,row,column,...bits]);
const canvas=document.createElement('canvas');let context;
function pixels(frame){canvas.width=frame.width;canvas.height=frame.height;context=canvas.getContext('2d');context.putImageData(new ImageData(frame.data,frame.width,frame.height),0,0);return{...frame,data:context.getImageData(0,0,frame.width,frame.height).data};}
const at=(frame,x,y)=>Array.from(frame.data.slice((y*frame.width+x)*4,(y*frame.width+x)*4+4));
function assert(value,message){if(!value)throw new Error(message);}
function equal(a,b,message='Bytes differ'){assert(a.length===b.length&&a.every((v,i)=>v===b[i]),message);}
const render=(bytes,time=10,options)=>pixels(createCDGDecoder(bytes,options).renderAt(time));
async function check(name,fn){try{await fn();checks.push({name,passed:true});}catch(error){checks.push({name,passed:false,error:error.message});}}
export async function runCDGChecks(){
 checks.length=0;$('#status').textContent='Running actual Canvas byte checks…';
 await check('Actual Canvas: full dimensions, upper CLUT and asymmetric tile orientation',()=>{const frame=render(join(clut(),clut(true),tile(0,0,0,15,[32,1,...Array(10).fill(0)])));equal([frame.width,frame.height],[300,216]);equal(at(frame,0,0),[255,255,255,255]);equal(at(frame,5,0),[0,0,0,255]);equal(at(frame,5,1),[255,255,255,255]);});
 await check('Existing indexed pixels recolor when CLUT changes',()=>{const decoder=createCDGDecoder(join(clut(),packet(1,[1]),clut(false,[0,0x0f0,...colors.slice(2)])));equal(at(pixels(decoder.renderAt(1/300)),20,20),[255,0,0,255]);equal(at(pixels(decoder.renderAt(2/300)),20,20),[0,255,0,255]);});
 await check('Two XOR commands restore exact Canvas pixels',()=>{const decoder=createCDGDecoder(join(clut(),packet(1,[1]),tile(8,20,0,2,Array(12).fill(63),true),tile(8,20,0,2,Array(12).fill(63),true)));const before=pixels(decoder.renderAt(1/300)).data;const during=pixels(decoder.renderAt(2/300));equal(at(during,120,96),[0,0,255,255]);equal(before,pixels(decoder.renderAt(3/300)).data);});
 for(const [name,h,v,dx,dy,edge] of [['right',16,0,6,0,[0,50]],['left',32,0,-6,0,[299,50]],['down',0,16,0,12,[50,0]],['up',0,32,0,-12,[50,215]]])await check('Scroll Preset '+name+': marker movement and newly exposed color',()=>{const frame=render(join(clut(),tile(),packet(20,[3,h,v])));equal(at(frame,120+dx,96+dy),[255,0,0,255]);equal(at(frame,...edge),[0,0,255,255]);});
 for(const [name,h,v,row,col,x,y] of [['right',16,0,4,49,0,48],['left',32,0,4,0,294,48],['down',0,16,17,20,120,0],['up',0,32,0,20,120,204]])await check('Scroll Copy '+name+': marker wraps into opposite edge',()=>equal(at(render(join(clut(),tile(row,col),packet(24,[0,h,v]))),x,y),[255,0,0,255]));
 await check('Combined diagonal scroll and inverse restore the full frame',()=>{const decoder=createCDGDecoder(join(clut(),tile(0,0),tile(17,49,0,2),packet(24,[0,16,32]),packet(24,[0,32,16])));equal(pixels(decoder.renderAt(2/300)).data,pixels(decoder.renderAt(4/300)).data);});
 await check('Fine offsets are absolute; cropped output samples the same visible pixels',()=>{const decoder=createCDGDecoder(join(clut(),tile(1,1,0,1,[...Array(11).fill(32),1]),packet(20,[0,5,11]),packet(20,[0,5,11])));const full=pixels(decoder.renderAt(2/300)),crop=pixels(decoder.renderAt(3/300,{crop:true}));equal([crop.width,crop.height],[288,192]);equal(at(full,6,12),[255,0,0,255]);equal(at(full,6,13),[0,0,0,255]);equal(at(crop,0,0),at(full,6,12));});
 await check('Index profile transparency clears alpha and a new key restores it',()=>{const decoder=createCDGDecoder(join(clut(),packet(1,[1]),packet(28,[1]),packet(28,[0])));assert(at(pixels(decoder.renderAt(2/300)),20,20)[3]===0,'Key alpha must be0');equal(at(pixels(decoder.renderAt(3/300)),20,20),[255,0,0,255]);});
 await check('Explicit alpha-table profile reaches alpha3 and127 in real Canvas',()=>{const alpha=Array(16).fill(0);alpha[1]=63;alpha[2]=32;const frame=render(join(clut(),packet(1,[1]),tile(8,20,0,2),packet(28,alpha)),1,{transparency:'alpha-table'});assert(at(frame,20,20)[3]===3,'Expected alpha3');assert(at(frame,120,96)[3]===127,'Expected alpha127');});
 await check('Packet300 changes Canvas at1second; timing packets are retained',()=>{const packets=Array.from({length:301},()=>packet(0,[],0));packets[0]=clut();packets[300]=packet(1,[1]);const decoder=createCDGDecoder(join(...packets));equal(at(pixels(decoder.renderAt(.99999)),100,100),[0,0,0,255]);const frame=pixels(decoder.renderAt(1));equal(at(frame,100,100),[255,0,0,255]);assert(frame.packetCursor===301,'Cursor must count complete consumed packets');});
 await check('Malformed bounds/trailing bytes are diagnosed without corrupting visible pixels',()=>{const bytes=join(clut(),tile(18,0),tile(0,50),tile());const trailing=new Uint8Array(bytes.length+7);trailing.set(bytes);const decoder=createCDGDecoder(trailing),frame=pixels(decoder.renderAt(9));equal(at(frame,120,96),[255,0,0,255]);assert(frame.diagnostics.invalidTiles===2&&frame.diagnostics.trailingBytes===7,'Expected two skipped invalid tiles and trailing7bytes');});
 await check('Backward target samples equal a fresh decoder through actual Canvas',()=>{const bytes=join(clut(),packet(1,[1]),tile(),packet(24,[0,16,16]),packet(28,[1]),packet(1,[2]));const decoder=createCDGDecoder(bytes);for(const time of [0,.01,.02,.015,.003,0,.017])equal(pixels(decoder.renderAt(time)).data,render(bytes,time).data);});
 await check('Copied input and prefix diagnostics remain stable over duplicate renders/replay',()=>{const bytes=join(clut(),tile(18,0),tile()),decoder=createCDGDecoder(bytes);bytes.fill(0);const first=pixels(decoder.renderAt(1));decoder.renderAt(0);const second=pixels(decoder.renderAt(1));equal(first.data,second.data);assert(second.diagnostics.invalidTiles===1&&second.diagnostics.decodedPackets===3,'Replay inflated prefix statistics');});
 await check('Reset clears prior graphics and disposal rejects reuse',()=>{const decoder=createCDGDecoder(join(clut(),packet(1,[1])));decoder.renderAt(1);decoder.reset();equal(at(pixels(decoder.renderAt(0)),20,20),[0,0,0,255]);decoder.dispose();let rejected=false;try{decoder.renderAt(0);}catch{rejected=true;}assert(rejected&&decoder.diagnostics().retainedInputBytes===0,'Disposed decoder retained input or allowed rendering');});
 await check('PNG encoding/decoding preserves actual keyed alpha and opaque markers',async()=>{const frame=render(join(clut(),packet(1,[1]),tile(8,20,0,2),packet(28,[1])));const image=new Image();image.src=canvas.toDataURL('image/png');await image.decode();const png=document.createElement('canvas');png.width=300;png.height=216;png.getContext('2d').drawImage(image,0,0);const data=png.getContext('2d').getImageData(0,0,300,216).data;assert(data[(20*300+20)*4+3]===0,'PNG lost transparency');equal(Array.from(data.slice((96*300+120)*4,(96*300+120)*4+4)),[0,255,0,255]);assert(frame.width===png.width,'PNG size mismatch');});
 const result={scope:'Executed original CD+G decoder→Canvas2D bytes and PNG. No Serato equivalence, MP3 pairing, capture or audible sync acceptance claimed.',passed:checks.filter(x=>x.passed).length,failed:checks.filter(x=>!x.passed).length,checks:[...checks]};$('#results').textContent=JSON.stringify(result,null,2);$('#status').textContent=`${result.passed}/${checks.length} passed; ${result.failed} failed.`;return result;
}
$('#run').onclick=async()=>{const button=$('#run');button.disabled=true;try{await runCDGChecks();}catch(error){$('#status').textContent='Harness failed: '+error.message;}finally{button.disabled=false;}};

const packets=Array.from({length:1200},()=>packet(0,[],0));packets[0]=clut();packets[1]=clut(true);packets[2]=packet(1,[0]);packets[3]=packet(2,[3]);packets[150]=tile(8,20,0,15);packets[300]=packet(1,[2]);packets[600]=packet(1,[3]);packets[900]=packet(1,[4]);const fixture=join(...packets),previewDecoder=createCDGDecoder(fixture);
function wav(){const rate=16000,seconds=4,count=rate*seconds,buffer=new ArrayBuffer(44+count*2),v=new DataView(buffer);const text=(offset,string)=>[...string].forEach((c,i)=>v.setUint8(offset+i,c.charCodeAt(0)));text(0,'RIFF');v.setUint32(4,36+count*2,true);text(8,'WAVE');text(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);text(36,'data');v.setUint32(40,count*2,true);for(let i=0;i<count;i++){const t=i/rate,local=t%0.5,envelope=local<.1?Math.sin(Math.PI*local/.1):0;v.setInt16(44+i*2,Math.round(Math.sin(2*Math.PI*(220+Math.floor(t)*110)*t)*envelope*6000),true);}return buffer;}
const audioBlob=new Blob([wav()],{type:'audio/wav'}),audio=$('#fixture-audio'),audioURL=URL.createObjectURL(audioBlob);audio.src=audioURL;let animation=0;
function preview(){const t=audio.currentTime||0,frame=previewDecoder.renderAt(t),ctx=$('#preview').getContext('2d');ctx.putImageData(new ImageData(frame.data,frame.width,frame.height),0,0);$('#fixture-time').value=t;$('#fixture-state').textContent=`Audio position ${t.toFixed(3)}s · ${frame.packetCursor}/${frame.diagnostics.totalPackets} packets`;}
function loop(){preview();if(!audio.paused&&!audio.ended)animation=requestAnimationFrame(loop);}
audio.onplay=()=>{cancelAnimationFrame(animation);loop();};audio.onpause=audio.onended=()=>{cancelAnimationFrame(animation);preview();};audio.onseeked=preview;$('#fixture-time').oninput=event=>{audio.currentTime=Number(event.target.value);preview();};
function download(name,blob){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#download-cdg').onclick=()=>download('open-play-generated.cdg',new Blob([fixture],{type:'application/octet-stream'}));$('#download-wav').onclick=()=>download('open-play-generated.wav',audioBlob);
window.addEventListener('beforeunload',()=>{cancelAnimationFrame(animation);audio.pause();URL.revokeObjectURL(audioURL);previewDecoder.dispose();});preview();
